// 1. Grab the AI's text response from the HTTP Request node
let aiText = $input.first().json.choices[0].message.content;

// 2. Clean it (remove markdown backticks if the model ever adds them)
aiText = aiText.replace(/```json/g, "").replace(/```/g, "").trim();

// 3. Parse the AI's text into a real object
const aiAnalysis = JSON.parse(aiText);

// 4. Grab the original Wazuh alert from the Webhook node
const wazuhData = $('Webhook from Wazuh').first().json.body;
const wazuhLevel = wazuhData.rule.level || 0;

// 5. --- THE SCORING SYSTEM ---
let riskScore = 0;

// Base score: Wazuh rule level (e.g. 12)
riskScore += wazuhLevel;

// AI logic points
if (aiAnalysis.verdict === "True Positive") { riskScore += 50; }
if (aiAnalysis.severity === "High") { riskScore += 20; }

// 6. Package everything into the Case File for the next agents
return [{
  json: {
    final_score: riskScore,
    ai_verdict: aiAnalysis.verdict,
    ai_severity: aiAnalysis.severity,
    ai_summary: aiAnalysis.summary,
    ai_ioc: aiAnalysis.ioc,
    wazuh_level: wazuhLevel,
    original_alert: wazuhData
  }
}];

