// AI response comes from the previous node (Defense Agent HTTP)
const raw = $input.first().json.choices[0].message.content;
const clean = raw.replace(/```json/g, "").replace(/```/g, "").trim();
const plan = JSON.parse(clean);

// Full Case File is pulled directly from the Scoring node
const incoming = $('Scoring').first().json;

return [{
  json: {
    ...incoming,
    response_action: plan.action,
    response_target: plan.target,
    response_justification: plan.justification,
    case_status: "CRITICAL - CONTAINMENT ORDERED",
    disposition_by: "AI Defense Agent (Tier-3, automated)"
  }
}];

// Fetch the original alert from the Scoring node
const scoringData = $('Scoring').first().json;
const originalAlert = scoringData.original_alert || {};

// Initialize default values
let iocType = 'unknown';
let iocValue = null;
let agentName = originalAlert.data?.agent?.name || 'unknown';

// 1. Try to extract File Hash (Sysmon Event 15 usually has a 'hashes' field)
const hashes = originalAlert.data?.win?.eventdata?.hashes;
if (hashes) {
  // Example format: "SHA256=275a021bbfb6489e54d471899f7db9d1663fc695ec2fe2e2c4d60853f3a6b2c4"
  const sha256Match = hashes.match(/SHA256=([a-fA-F0-9]{64})/);
  if (sha256Match) {
    iocType = 'hash';
    iocValue = sha256Match[1];
  }
}

// 2. If no hash found, try to extract an IP address (e.g., from a network connection alert)
if (!iocValue) {
  const ip = originalAlert.data?.win?.eventdata?.ipAddress || originalAlert.data?.srcip;
  if (ip && ip !== '127.0.0.1') {
    iocType = 'ip';
    iocValue = ip;
  }
}

// Return the extracted data so the next nodes can use it
return [
  {
    json: {
      ioc_type: iocType,
      ioc_value: iocValue,
      agent_name: agentName,
      original_alert: originalAlert,
      ai_summary_tier1: scoringData.ai_summary || "No Tier 1 summary provided"
    }
  }
];

const alert = $input.first().json.body;
const eventData = alert.data?.win?.eventdata || {};
const agentId = alert.agent?.id || "000";

let iocs = {
    agent_id: agentId,
    hashes: [],
    urls: [],
    ips: []
};

// 1. Extract Hashes (Sysmon EID 15 or Defender)
if (eventData.Hashes) {
    const hashMatch = eventData.Hashes.match(/SHA256=([a-fA-F0-9]{64})/i);
    if (hashMatch) iocs.hashes.push(hashMatch[1]);
}

// 2. Extract URLs (Sysmon EID 15 TargetFilename or Defender path)
if (eventData.TargetFilename) iocs.urls.push(eventData.TargetFilename);
if (eventData.commandLine) {
    const urlMatch = eventData.commandLine.match(/http[s]?:\/\/[^\s]+/i);
    if (urlMatch) iocs.urls.push(urlMatch[0]);
}

// 3. Extract IP (from Sysmon NetworkConnect or Agent IP)
if (eventData.DestinationIp) iocs.ips.push(eventData.DestinationIp);
if (alert.agent?.ip) iocs.ips.push(alert.agent.ip);

return [{
    json: {
        original_alert: alert,
        iocs: iocs,
        timestamp: new Date().toISOString()
    }
}];

// 1. Reach back to get the IOCs and Original Alert
const iocsNode = $('Extract IOCs').first().json;

// 2. Reach back to get the Wazuh Timeline (last 10 alerts)
// OpenSearch returns data inside hits.hits, we just want the descriptions/logs
const timelineNode = $('Get Wazuh Timeline').first().json;
const recentActivity = (timelineNode.hits?.hits || []).map(hit => 
    hit._source.rule?.description || hit._source.full_log || "Unknown Event"
);

// 3. Grab the current input (VirusTotal Response)
const vtResponse = $input.first().json;

// 4. Extract the juicy VT stats (handling cases where VT returned an error/404)
let vtStats = "No VirusTotal data available.";
let vtClassification = "Unknown";
if (vtResponse.data && vtResponse.data.attributes) {
    vtStats = vtResponse.data.attributes.last_analysis_stats;
    vtClassification = vtResponse.data.attributes.popular_threat_classification?.suggested_threat_label || "Unclassified";
}

// 5. Build the final Context Package for the Tier-3 Agent
return [{
  json: {
    original_alert: iocsNode.original_alert,
    extracted_iocs: iocsNode.iocs,
    endpoint_timeline_last_1h: recentActivity,
    virustotal_stats: vtStats,
    virustotal_threat_label: vtClassification
  }
}];

