// 1. Clean and parse the AI's JSON response
let raw = ($input.first().json.choices?.[0]?.message?.content) || "";
let clean = raw.replace(/```json/gi, "").replace(/```/g, "").trim();
let analysis = null;
const mj = clean.match(/\{[\s\S]*\}/);
if (mj) {
    let t = mj[0].replace(/[\u0000-\u001f]+/g, " ").replace(/,\s*([}\]])/g, "$1");
    try { analysis = JSON.parse(t); } catch (e) { analysis = null; }
}
if (!analysis || typeof analysis.verdict !== "string") {
    analysis = {
        verdict: "Suspicious",
        malware_family: "Unknown",
        mitre_techniques: [],
        behavior_summary: "AI response could not be parsed as JSON - flagged for manual review. Raw output: " + raw.slice(0, 300),
        yara_rule: 'rule unparsed_ai_response { condition: false }'
    };
}(clean);

// 2. Grab the original alert data from the beginning of the flow
const iocsData = $('Extract IOCs').first().json;
const original_alert = iocsData.original_alert;
const wazuhLevel = original_alert.rule?.level || 0;

// 3. --- THE TIER-3 SCORING SYSTEM ---
let riskScore = wazuhLevel;
let case_status = "";

if (analysis.verdict === "Malicious") {
    riskScore += 60; // Heavy penalty for confirmed malware
    case_status = "CRITICAL - MALICIOUS";
} else if (analysis.verdict === "Suspicious") {
    riskScore += 30; // Moderate penalty for LOLBINs/Suspicious behavior
    case_status = "FORENSIC - REQUIRES HUMAN REVIEW";
} else {
    case_status = "CLOSED - BENIGN";
}

// 4. Package the ultimate Case File for the Switch and Dashboard
// Build the flat case document here (real JS, no expression-evaluator limits).
const ag = original_alert.agent || {};
const rl2 = original_alert.rule || {};
const od = original_alert.data || {};
const ed = (od.win && od.win.eventdata) || {};
const io2 = iocsData.iocs || {};
const case_ioc = (io2.hashes && io2.hashes[0]) ||
                 (io2.urls && io2.urls[0]) ||
                 od.srcip || ed.path || "n/a";
const case_doc = {
  timestamp: new Date().toISOString(),
  alert_id: original_alert.id !== undefined ? original_alert.id : null,
  agent_name: ag.name || "unknown",
  agent_ip: ag.ip !== undefined ? String(ag.ip) : "n/a",
  rule_id: rl2.id !== undefined ? rl2.id : null,
  rule_description: rl2.description || "",
  threat_name: (analysis.malware_family && analysis.malware_family !== "Unknown" && analysis.malware_family !== "unknown")
      ? analysis.malware_family
      : (rl2.description || case_ioc || "Security event"),
  ioc: case_ioc,
  tier3_verdict: analysis.verdict,
  behavior_summary: analysis.behavior_summary || "",
  mitre_techniques: analysis.mitre_techniques || [],
  yara_rule: analysis.yara_rule || "",
  final_score: riskScore,
  case_status: case_status,
};

return [{
  json: {
    // Original Data
    original_alert: original_alert,
    extracted_iocs: iocsData.iocs,

    // Tier-3 Intelligence
    tier3_verdict: analysis.verdict,
    malware_family: analysis.malware_family,
    mitre_techniques: analysis.mitre_techniques,
    behavior_summary: analysis.behavior_summary,
    yara_rule: analysis.yara_rule,

    // Final Scoring
    final_score: riskScore,
    case_status: case_status,
    case_doc: case_doc,
  }
}];

// Rebuild the Tier-3 case file and attach the Active Response outcome
const caseFile = $('Sample Triage').first().json;
const resp = $input.first().json;
let dispatched = false;
let detail = null;
if (resp && resp.data && Array.isArray(resp.data.affected_items)) {
  dispatched = resp.data.affected_items.length > 0;
  detail = resp.data;
} else if (resp && resp.error) {
  detail = resp.error;
}
const prevDoc = caseFile.case_doc || {};
const caseDoc = Object.assign({}, prevDoc, { ar_dispatched: dispatched, ar_detail: detail });
return [{ json: Object.assign({}, caseFile, { ar_dispatched: dispatched, ar_detail: detail, case_doc: caseDoc }) }];

// Decide whether this case warrants pulling the sample off the endpoint
const item = $input.first().json;
const oa = item.original_alert || {};
const od = oa.data || {};
const win = od.win || {};
const ed = win.eventdata || {};
const sys = od.syscheck || {};
const ack = od.ack || {};
const virustotal = od.virustotal || {};
const resources = od.resources || od.Resources || [];

// Extract candidate paths from ALL possible fields
const candidates = [];

// Standard Wazuh/Windows fields
const standard = [
  ed.path, ed.targetFilename, ed.TargetFilename,
  od.targetFilename, od.TargetFilename,
  sys.path, sys.pathName,
  (od.audit && od.audit.file && od.audit.file.path),
  (ack.path), (ack.targetFileName), (ack.targetFilename),
  (virustotal.meaningful_name),
  (virustotal.malicious_file_path),
  (virustotal.path)
];

candidates.push(...standard.filter(x => x && typeof x === 'string'));

// Defender resources: ["file:_C:\Users\...", "containerfile:_...", "webfile:_..."]
if (resources.length) {
  for (const r of resources) {
    if (typeof r === 'string') {
      // Strip Defender prefixes: file:_, containerfile:_, webfile:_
      let clean = r.replace(/^(file:|containerfile:|webfile:)_/i, '');
      // Extract Windows paths
      const m = clean.match(/[A-Za-z]:\\[^"\s]+/g);
      if (m) candidates.push(...m);
      // Also grab bare paths
      if (!m) candidates.push(clean);
    }
  }
}

// Also check case_doc if it already has a path
if (item.case_doc && item.case_doc.sample_path) {
  candidates.push(item.case_doc.sample_path);
}

// Deduplicate and score paths: prefer executables, avoid .crdownload/.tmp/.part
const seen = new Set();
const scored = [];
for (const c of candidates) {
  if (!c || typeof c !== 'string') continue;
  const norm = c.trim().replace(/^file:_/i, '').replace(/^containerfile:_/i, '').replace(/^webfile:_/i, '');
  if (!norm || seen.has(norm)) continue;
  seen.add(norm);
  let score = 0;
  if (/\.(exe|dll|sys|bat|cmd|ps1|scr|com|pif|msi|jar|zip|rar|7z)$/i.test(norm)) score += 10;
  if (/\.(crdownload|tmp|part|temp|download)$/i.test(norm)) score -= 20;  // avoid partial downloads
  if (/^[A-Za-z]:\\/.test(norm)) score += 5;  // absolute Windows path
  if (norm.includes('mimikatz') || norm.includes('mimidrv') || norm.includes('mimilib')) score += 15;
  scored.push({ path: norm, score });
}

scored.sort((a, b) => b.score - a.score);
const bestPath = scored.length ? scored[0].path : '';

// Final check: does it look like a file?
const looksLikeFile = bestPath && (bestPath.includes('.') || bestPath.includes('\\'));

const wantsAnalysis = (item.tier3_verdict === 'Malicious') ||
                      (item.tier3_verdict === 'Suspicious' && Number(item.final_score) >= 30);

item.case_doc = item.case_doc || {};
if (wantsAnalysis && looksLikeFile) {
  item.case_doc.needs_sample = true;
  item.case_doc.sample_path = bestPath;
  item.case_doc.sample_source = 'triage';
  item.case_doc.sample_status = 'requested';
  item.case_doc.all_candidates = scored.map(s => s.path).slice(0, 5);
} else {
  item.case_doc.needs_sample = false;
  item.case_doc.sample_path = bestPath || '';
  item.case_doc.sample_status = wantsAnalysis ? 'no-valid-path' : 'not-needed';
  item.case_doc.all_candidates = scored.map(s => s.path).slice(0, 5);
}
item.sample_path = item.case_doc.sample_path;
item.needs_sample = item.case_doc.needs_sample;
return [{ json: item }];

const rawIn = $input.first().json;
const b = rawIn.body || rawIn;
const name = String(b.path || 'sample.bin').split('\\').pop();
return [{ json: {
    alert_id: b.alert_id || null,
    path: b.path || 'unknown',
    sha256: b.sha256 || '',
    size: Number(b.size) || 0
  }, binary: { data: {
    data: b.data_b64,
    mimeType: 'application/octet-stream',
    fileName: name
  } } }];

const r = $input.first().json;
const res0 = (r.results && r.results[0]) || {};
const rule0 = ((r.rules && r.rules[0]) || {});
const done = r.status === 'completed' && r.results && r.results.length > 0;
const alertId = $('Build Binary').first().json.alert_id;
const upd = {
  query: { term: { alert_id: alertId } },
  script: {
    source: "ctx._source.sample_analyzed = true; ctx._source.yarakin_status = params.st; ctx._source.yarakin_verdict = params.v; ctx._source.yarakin_family = params.fam; ctx._source.yarakin_summary = params.sum; ctx._source.yarakin_rule_name = params.rn; ctx._source.yara_rule = params.yara; ctx._source.yarakin_report_url = params.pdf;",
    lang: "painless",
    params: {
      st: done ? 'completed' : 'timeout',
      v: res0.verdict || null,
      fam: res0.family || null,
      sum: res0.summary || '',
      rn: res0.rule_name || null,
      yara: rule0.yara || null,
      pdf: res0.report_pdf_url || null
    }
  }
};
return [{ json: { update_body: upd, alert_id: alertId } }];
